import { readInjectedAgentSessionId } from '../../shared/agent-session/lifecycle/launch/agent-session-caller-env'
import {
  AGENT_SESSION_ATTACHMENT_CHUNK_BYTES,
  sanitizeAgentSessionAttachmentName
} from '../../shared/agent-session/agent-session-attachments'
import { RuntimeClientError } from '../runtime/connection/types'
import { printResult } from '../output/command-result-output'
import type { HandlerContext } from '../dispatch/dispatch'

/** The CLI accepts generated bytes on stdin. The host never opens a caller-supplied path. */
export async function replyWithGeneratedFile(
  name: string,
  client: HandlerContext['client'],
  json: boolean
): Promise<void> {
  const sessionId = readInjectedAgentSessionId()
  if (
    !sessionId ||
    !name.trim() ||
    sanitizeAgentSessionAttachmentName(name) !== name ||
    process.stdin.isTTY
  ) {
    throw new RuntimeClientError(
      'invalid_argument',
      'Pipe generated bytes into --file-stdin with a plain filename from the Feishu DM turn.'
    )
  }
  const chunks: Buffer[] = []
  let size = 0
  for await (const chunk of process.stdin) {
    const bytes = Buffer.from(chunk)
    size += bytes.length
    if (size > AGENT_SESSION_ATTACHMENT_CHUNK_BYTES) {
      throw new RuntimeClientError(
        'invalid_argument',
        'Generated files must fit in one attachment chunk (384 KiB).'
      )
    }
    chunks.push(bytes)
  }
  if (!size) {
    throw new RuntimeClientError('invalid_argument', 'No file bytes were supplied.')
  }
  const result = await client.call<{ staged: boolean }>('bots.feishuLocal.stageFile', {
    sessionId,
    name,
    base64: Buffer.concat(chunks, size).toString('base64')
  })
  printResult(result, json, () => 'File staged for the final Feishu reply.')
}
